// Renders server/fulfillment/catalog.mjs from the ledger. The output is the
// only list the checkout and fulfiller accept, so it is generated, never edited.
import { fulfillmentFromLedger } from "./ledger.mjs";

const HEADER = `/**
 * The only variants the automatic fulfiller may submit.  This is deliberately
 * a source-controlled allow list matched to the active products.json
 * records.  Never accept a client SKU, title, or price as a
 * substitute for a Square variation id.
 *
 * GENERATED by \`npm run catalog -- generate\` from catalog/ledger.json.
 * Edit the ledger (through the catalog engine), never this file.
 */
`;

export function renderFulfillmentCatalog(ledger) {
  const entries = fulfillmentFromLedger(ledger);
  const lines = Object.entries(entries).map(([id, value]) => {
    const fields = Object.entries(value).map(([key, field]) => `${key}: ${JSON.stringify(field)}`).join(", ");
    return `  ${JSON.stringify(id)}: { ${fields} },`;
  });
  return `${HEADER}export const AHA_FULFILLMENT_CATALOG = Object.freeze({\n${lines.join("\n")}\n});\n\nexport const AHA_PRIVATE_LABEL = ${JSON.stringify(ledger.privateLabel)};\n`;
}
